export function SpanElement({
  before = "{{before}}",
  highlighted = "{{highlighted}}",
  after = "{{after}}",
  accent = "{{accent}}",
}) {
  return (
    <p style={{ width: 340, boxSizing: "border-box", font: "15px/1.6 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: "18px 20px", borderRadius: 12, margin: 0 }}>
      {before}
      <span style={{ fontWeight: 700, color: accent }}>{highlighted}</span>
      {after} A <code style={{ background: "#24143012", padding: "1px 5px", borderRadius: 4, fontSize: 13 }}>&lt;span&gt;</code> carries no meaning — it exists purely to style a run of inline text.
    </p>
  );
}
